using UnityEngine; public class ParentCoach:MonoBehaviour{ public TalkSingClapTTS TTS; string[] tips={"Introduce yourself: Hi, it's Mommy. I am on your left.","Narrate: I'm lifting your right hand to touch the soft blanket.","Warn before touch: I'm going to pick you up now."}; void OnEnable(){ if(!TTS) TTS=FindObjectOfType<TalkSingClapTTS>(); } public void NextTip(){ if(TTS) TTS.Talk(tips[Random.Range(0,tips.Length)]);} }